window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-42301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανταστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 95 na letra φ · nº geral 42301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em imaginação; de modo imaginário.</p></section></article>\n<article id=\"entry-dgp-42302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανταστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 96 na letra φ · nº geral 42302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode imaginar ♦ τὸ φαν­τασ­τόν 2 imaginação; visão. 〈φαντάζω〉</p></section></article>\n<article id=\"entry-dgp-42303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανῶ, εῖς, εῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 97 na letra φ · nº geral 42303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανῶ, ῇς, ῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 98 na letra φ · nº geral 42304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 pas. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 99 na letra φ · nº geral 42305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. claramente. 〈φανός〉</p></section></article>\n<article id=\"entry-dgp-42306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάο</h1><div class=\"entry-meta\"><span>DGP · ordem 100 na letra φ · nº geral 42306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. méd. de φημί.</p></section></article>\n<article id=\"entry-dgp-42307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάος, φάεος-φάους,</h1><div class=\"entry-meta\"><span>DGP · ordem 101 na letra φ · nº geral 42307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. φῶς, φωτός (τό) poét. 1 luz; claridade (do sol, da vida): ὁρᾶν φάος ἠελίοιο hom. ou φάος βλέπειν ésql. ver luz do sol, i.e., viver, ἐν φάει εἶναι sóf. estar vivo, οἱ ἐν φάει ésql. os vivos, λείπειν φάος ἠελίοιο hes. abandonar a luz do sol, morrer 2 luz do dia; dia: νόστιμον βλέπειν φάος ésql. ver a luz do retorno, ἔτι φάους ὄντος xen. enquanto ainda é dia, ἐν φάει hom. em pleno dia ou sob um céu claro, ἐς φάος ἐλθεῖν pínd. vir à luz, nascer, εἰς φάος ἀφικέσθαι hes. vir à luz do dia, à terra, κατὰ φάος καὶ νύκτας eur. dia e noite 3 luz; clarão (de tocha, de fogo) 4 luz, brilho do olhar 5 olho: τὸ φῶς Κύκλωπος eur. o olho do Ciclope 6 luz, ref. a pessoa; alegria ou glória: Τηλεμάχε, γλυκυρὸν φάος hom. Telêmaco, doce luz, Ἀκραγαντίνων φάος pínd. luz dos agrigentinos.</p></section></article>\n<article id=\"entry-dgp-42308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαραγγώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 102 na letra φ · nº geral 42308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 repleto de ravinas ou de vales profundos 2 que brota nas ravinas (planta) 3 que se precipita ou corre pelas ravinas (rio). 〈φαράγξ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-42309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάραγξ, αγγος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 103 na letra φ · nº geral 42309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escarpadura abrupta; rocha talhada a pique 2 ravina; precipício 3 margem escarpada; falésia 4 precipício; abismo.</p></section></article>\n<article id=\"entry-dgp-42310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαραώ</h1><div class=\"entry-meta\"><span>DGP · ordem 104 na letra φ · nº geral 42310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (ὁ) faraó, título real egípcio.</p></section></article>\n<article id=\"entry-dgp-42311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρέτρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 105 na letra φ · nº geral 42311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aljava; carcás. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρετρεών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 106 na letra φ · nº geral 42312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φαρέτρα.</p></section></article>\n<article id=\"entry-dgp-42313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρέτρη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 107 na letra φ · nº geral 42313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φαρέτρα.</p></section></article>\n<article id=\"entry-dgp-42314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαρισαῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 108 na letra φ · nº geral 42314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. e crist. fariseu.</p></section></article>\n<article id=\"entry-dgp-42315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 109 na letra φ · nº geral 42315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 ter necessidade de remédio 2 ter o espírito perturbado. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 110 na letra φ · nº geral 42316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 medicamento 2 medicamento purgativo 3 envenenamento 4 sortilégio; feitiçaria; magia. 〈φαρμακεύω〉</p></section></article>\n<article id=\"entry-dgp-42317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμάκεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 111 na letra φ · nº geral 42317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φαρμακίς.</p></section></article>\n<article id=\"entry-dgp-42318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 112 na letra φ · nº geral 42318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que prepara ou administra medicamentos 2 aquele que administra veneno; envenenador 3 mago; feiticeiro. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 113 na letra φ · nº geral 42319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne à preparação ou administração de medicamentos ♦ ἡ φαρμακευτική 2 arte de preparar ou administrar medicamentos. 〈φαρμακεύω〉</p></section></article>\n<article id=\"entry-dgp-42320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 114 na letra φ · nº geral 42320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar um medicamento a alguém, ac.; medicar 2 Medic. purgar 3 envenenar. 4 administrar bebida mágica em alguém, ac. 5 praticar ato de magia 6 preparar; temperar um alimento, ac., com algo, dat. ♦ méd. 7 tomar um remédio. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 115 na letra φ · nº geral 42321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 medicamento 2 Medic. purgativo. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 116 na letra φ · nº geral 42322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 venenosa ♦ ἡ φαρμακίς 2 maga; feiticeira. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρμακον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 117 na letra φ · nº geral 42323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 droga medicinal; medicamento; remédio preparado (ungüento, sólido, beberagem) contra algo, gen. ou πρός e ac.: φ. νόσου ésql. remédio contra a doença; φ. βλάβης ésql. remédio contra os males, φάρμακον ἐπιτιθέναι hom. aplicar um remédio, φάρμακον ἐπιπάσσειν hom. espalhar um pó sobre uma ferida, φάρμακον προσαλείφειν τινί hom. aplicar um ungüento em alguém, πίνειν φάρμακον hom. beber uma poção 2 droga nefasta; veneno: φάρμακον ἀνδροφόνον hom. veneno mortal 3 poção mágica; filtro 4 operação de magia (canto, encantamento, fórmula etc.) 5 droga para tingir; tintura; cosmético 6 remédio; solução 7 meio; expediente.</p></section></article>\n<article id=\"entry-dgp-42324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακοποσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 118 na letra φ · nº geral 42324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de beber um remédio 2 ação de beber um veneno. 〈φάρμακον, πότος〉</p></section></article>\n<article id=\"entry-dgp-42325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακοπώλης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 119 na letra φ · nº geral 42325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">farmacêutico. 〈φάρμακον, πωλέω〉</p></section></article>\n<article id=\"entry-dgp-42326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρμακος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 120 na letra φ · nº geral 42326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φαρμακός1, οῦ (ὁ) bíbl. envenenador; mago; feiticeiro. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακός2, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 121 na letra φ · nº geral 42327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que é imolado como vítima expiatória; bode expiatório 2 celerado; miserável; criminoso. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακοτρίβης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra φ · nº geral 42328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">triturador de drogas; preparador de medicamentos. 〈φάρμακον, τρίβω〉</p></section></article>\n<article id=\"entry-dgp-42329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra φ · nº geral 42329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 preparar; misturar (remédio) ♦ pas. 2 (flecha) ser envenenado 3 (pessoa) ser enfeitiçado. 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμακώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 124 na letra φ · nº geral 42330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cura; medicinal; salutar 2 que contém veneno; venenoso; envenenado 3 abundante em ervas ou substâncias venenosas ou plantas medicinais ♦ τὸ φαρμακῶδες 4 as drogas; os remédios. 〈φάρμακον, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-42331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρμαξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 125 na letra φ · nº geral 42331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tratamento com remédio; medicação 2 crist. feitiçaria 3 ato de temperar o ferro; têmpera (de metais). 〈φαρμάσσω〉</p></section></article>\n<article id=\"entry-dgp-42332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαρμάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 126 na letra φ · nº geral 42332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. φαρμάξω; perf. pas. πεφάρμαγμαι) 1 curar com medicamentos; dar um remédio; medicar 2 envenenar (flecha, fonte) 3 perturbar a razão com uma beberagem ou com práticas de feitiçaria 4 enfeitiçar 5 preparar, temperar com uma droga; misturar uma droga (ao vinho) 6 perfumar com essência ou óleo aromático 7 dar têmpera (a metais) 8 temperar (alimentos) 9 tingir (tecidos). 〈φάρμακον〉</p></section></article>\n<article id=\"entry-dgp-42333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαρνάβαζος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 127 na letra φ · nº geral 42333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Farnábazo, n. de h.</p></section></article>\n<article id=\"entry-dgp-42334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 128 na letra φ · nº geral 42334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eól. = φράξαι.</p></section></article>\n<article id=\"entry-dgp-42335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φᾶρος</h1><div class=\"entry-meta\"><span>DGP · ordem 129 na letra φ · nº geral 42335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φάρος, εος-ους (τό) 1 pedaço de tela; tela para vela 2 vela de navio 3 coberta de cama 4 mortalha 5 sobretudo; casaco. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάρος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 130 na letra φ · nº geral 42336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Faro, ilha da baía de Alexandria, famosa por seu farol.</p></section></article>\n<article id=\"entry-dgp-42337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαρσάλιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 131 na letra φ · nº geral 42337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Farsalo; farsálio ♦ ἡ Φαρσαλία 2 território de Farsalo; Farsália. 〈Φάρσαλος〉</p></section></article>\n<article id=\"entry-dgp-42338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάρσαλος1, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 132 na letra φ · nº geral 42338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Farsalo, cidade da Tessália.</p></section></article>\n<article id=\"entry-dgp-42339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάρσαλος2, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 133 na letra φ · nº geral 42339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Φαρσάλιος.</p></section></article>\n<article id=\"entry-dgp-42340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρσος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 134 na letra φ · nº geral 42340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedaço; porção; fragmento 2 quarteirão (da cidade) 3 cacho (de uva).</p></section></article>\n<article id=\"entry-dgp-42341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάρυγξ, υγγος,</h1><div class=\"entry-meta\"><span>DGP · ordem 135 na letra φ · nº geral 42341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. υγος (ὁ e ἡ) 1 goela 2 faringe 3 traqueia 4 barbela do boi.</p></section></article>\n<article id=\"entry-dgp-42342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάς, φᾶσα, φάν</h1><div class=\"entry-meta\"><span>DGP · ordem 136 na letra φ · nº geral 42342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. de φημί.</p></section></article>\n<article id=\"entry-dgp-42343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσγανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 137 na letra φ · nº geral 42343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espada; punhal 2 gladíolo, planta. 〈σφάζω〉</p></section></article>\n<article id=\"entry-dgp-42344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 138 na letra φ · nº geral 42344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. méd., φάσθε 2ª pl. imper. méd., φάσθω 3ª sing. imper. méd., de φημί.</p></section></article>\n<article id=\"entry-dgp-42345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φασί</h1><div class=\"entry-meta\"><span>DGP · ordem 139 na letra φ · nº geral 42345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. pres. ind. de φημί.</p></section></article>\n<article id=\"entry-dgp-42346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φασιανικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 140 na letra φ · nº geral 42346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Fasis; fasiano ♦ οἱ Φασιανικοί 2 habitantes do Fasis, na Cólquida. 〈Φασιανός〉</p></section></article>\n<article id=\"entry-dgp-42347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φασιανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 141 na letra φ · nº geral 42347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do Fasis, na Cólquida ou na Armênia ♦ ὁ Φασιανός 2 pássaro do Fasis; faisão. 〈Φᾶσις〉</p></section></article>\n<article id=\"entry-dgp-42348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φασίν</h1><div class=\"entry-meta\"><span>DGP · ordem 142 na letra φ · nº geral 42348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φασί.</p></section></article>\n<article id=\"entry-dgp-42349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσις1, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 143 na letra φ · nº geral 42349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 informação judiciária; acusação 2 denúncia; delação 3 aparição (de estrela). 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσις2, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 144 na letra φ · nº geral 42350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavra 2 declaração 3 afirmação 4 decisão; julgamento; sentença 5 bíbl. notícia. 〈φημί〉</p></section></article>\n<article id=\"entry-dgp-42351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φᾶσις, ιδος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 145 na letra φ · nº geral 42351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Fasis, n. de rio da Cólquida e da Armênia 2 Fasis, filho de Hélios.</p></section></article>\n<article id=\"entry-dgp-42352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 146 na letra φ · nº geral 42352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. at. e pas.) 1 dizer; declarar algo, ac. ou or. conj. (ὅτι, ὡς) ou inf. 2 prometer, com inf. fut. 3 dizer sim; falar afirmativamente; admitir; afirmar; οὐ φάσκειν negar 4 ter uma opinião; pensar; crer. 〈φημί〉</p></section></article>\n<article id=\"entry-dgp-42353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 147 na letra φ · nº geral 42353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forma; simulacro 2 aparição; visão: φ. ἀνθρώπου her. fantasma de homem, φ. γυναικός her. fantasma de mulher 3 sinal dos deuses; presságio 4 fenômeno celeste extraordinário 5 monstro; prodígio. 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάσσα,</h1><div class=\"entry-meta\"><span>DGP · ordem 148 na letra φ · nº geral 42354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. φάττα, ης (ἡ) pombo torcaz; pomba.</p></section></article>\n<article id=\"entry-dgp-42355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φασσοφόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 149 na letra φ · nº geral 42355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que mata as pombas ♦ ὁ φασσοφόνος 2 espécie de gavião. 〈φάσσα, πεφνεῖν〉</p></section></article>\n<article id=\"entry-dgp-42356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φασσοφόντης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 150 na letra φ · nº geral 42356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de gavião, ave de rapina diurna.</p></section></article>\n<article id=\"entry-dgp-42357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φατέον</h1><div class=\"entry-meta\"><span>DGP · ordem 151 na letra φ · nº geral 42357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb de φημί.</p></section></article>\n<article id=\"entry-dgp-42358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φατίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 152 na letra φ · nº geral 42358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φατίσω, aor. ἐφάτισα, perf. desus.; pas. aor. ἐφατίσθην, perf. πεφάτισμαι) 1 dizer; falar; declarar, or. inf. 2 prometer uma filha, ac., como esposa a alguém, dat.: τῷ τῆς θεᾶς σὴν παῖδ᾽ ἄλοχον φατίσας eur. tendo prometido sua filha como esposa ao filho da deusa ♦ pas. 3 ser dito: τὸ φατιζόμενον sóf., κατὰ τὰ φατισμένα como se diz 4 ser prometida como esposa: ἐμὴ φατισθεῖσα eur. a noiva que me foi prometida, minha noiva. 〈φάτις〉</p></section></article>\n<article id=\"entry-dgp-42359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάτις</h1><div class=\"entry-meta\"><span>DGP · ordem 153 na letra φ · nº geral 42359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom., voc. e ac. (ἡ) 1 aquilo que se diz de alguém ou de algo; boato; rumor; notícia sobre alguém, gen.: φάτιν φέρειν ésql. trazer uma notícia, φ. ἦλθέ μοι eur. chegou-me a notícia, φ. ἐπέρχεται sóf. um rumor avança, φάτιν αἴρειν sóf. fazer ressoar um rumor, κατὰ φάτιν her. como se divulgou, ὥσπερ ἡ φάτις sóf. como se diz, como se espalhou, ἡ φ. κεχώρηκε her. o rumor se espalhou, ὡς φάτις ὥρμηται her. como o rumor se espalhou, ὡς φάτις ἀνδρῶν sóf. conforme a fala dos homens, i.e., como contam, ὡς φάτις κρατεῖ ésql. a tradição prevalece 2 fama; renome 3 assunto de um discurso ou de uma conversa 4 palavra; linguagem; discurso 5 palavra de um deus; oráculo 6 augúrio 7 aviso dado por um sonho 8 língua; idioma. 〈φημί〉</p></section></article>\n<article id=\"entry-dgp-42360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάτνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 154 na letra φ · nº geral 42360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manjedoura; cocho para cavalos 2 estábulo para bois 3 vigas (de teto) 4 alvéolo (de dentes) 5 nebulosa da constelação de Câncer.</p></section></article>\n<article id=\"entry-dgp-42361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φατνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 155 na letra φ · nº geral 42361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. construir teto decorado com ornamentos encaixilhados. 〈φάτνη〉</p></section></article>\n<article id=\"entry-dgp-42362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάτνωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 156 na letra φ · nº geral 42362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 teto decorado com ornamentos encaixilhados 2 em navio, plataforma para lançamento de projéteis 3 Medic. alvéolo de dente. 〈φατνόω〉</p></section></article>\n<article id=\"entry-dgp-42363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φατνωματικός</h1><div class=\"entry-meta\"><span>DGP · ordem 157 na letra φ · nº geral 42363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">revestido de lambris. 〈φάτνωμα〉</p></section></article>\n<article id=\"entry-dgp-42364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάτο</h1><div class=\"entry-meta\"><span>DGP · ordem 158 na letra φ · nº geral 42364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. méd. ép. de φημί.</p></section></article>\n<article id=\"entry-dgp-42365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φατός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 159 na letra φ · nº geral 42365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode dizer ou exprimir: οὐ ou μὴ φ. indizível, inexprimível, inefável 2 famoso; célebre; notável. 〈φημί〉</p></section></article>\n<article id=\"entry-dgp-42366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάττα</h1><div class=\"entry-meta\"><span>DGP · ordem 160 na letra φ · nº geral 42366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = φάσσα.</p></section></article>\n<article id=\"entry-dgp-42367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαττάγης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 161 na letra φ · nº geral 42367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pangolim, animal.</p></section></article>\n<article id=\"entry-dgp-42368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάττιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 162 na letra φ · nº geral 42368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">termo afetivo, dim. de φάττα.</p></section></article>\n<article id=\"entry-dgp-42369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαυλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 163 na letra φ · nº geral 42369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">considerar vil; desprezar. 〈φαῦλος〉</p></section></article>\n<article id=\"entry-dgp-42370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαύλιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 164 na letra φ · nº geral 42370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de má qualidade (fruto): ἡ φαυλία ἐλαία luc. espécie de azeitona agreste carnuda, mas coberta com uma penugem semelhante a algodão. 〈φαῦλος〉</p></section></article>\n<article id=\"entry-dgp-42371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαῦλος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 165 na letra φ · nº geral 42371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de qualidade inferior 2 feio 3 mau; malévolo; maldoso com alguém, περί e ac. 4 defeituoso, imperfeito: ἵππος φ. xen. cavalo defeituoso, φ. αὐλητής plat. mau tocador de flauta, φ. τὴν γνώμην tuc. de inteligência medíocre, φ. μάχεσθαι eur. despreparado para combater 5 de baixo valor; vil; ordinário; comum: φαῦλα σιτία xen. alimentos grosseiros, φαῦλον ἱμάτιον xen. vestimenta comum 6 sem importância; insignificante: οὐ φαῦλον πρᾶγμα xen. negócio ou assunto importante 7 leviano; despreocupado; frívolo 8 negligente; indolente, preguiçoso: τὸ πλῆθος τὸ φαυλότερον eur. a multidão ignara 9 de um nível inferior 10 humilde; modesto 11 não complicado; simples 12 de baixo custo; frugal 13 fácil; cômodo ♦ οἱ φαυλότατοι 14 os soldados de última classe ♦ τὸ φαῦλον 15 o mal 16 a natureza frívola ou despreocupada da juventude.</p></section></article>\n<article id=\"entry-dgp-42372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαυλότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 166 na letra φ · nº geral 42372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mau estado (de uma veste); estado precário 2 pobreza (do solo) 3 simplicidade; simploriedade 4 falta de habilidade ou de bom senso; estupidez 5 ignorância 6 perversidade. 〈φαῦλος〉</p></section></article>\n<article id=\"entry-dgp-42373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαύλως</h1><div class=\"entry-meta\"><span>DGP · ordem 167 na letra φ · nº geral 42373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 mal; em mau estado; de maneira defeituosa: φ. κρίνειν ésql. julgar mal, φ. ἔχειν hipócr. estar em mau estado 2 negligentemente; despreocupadamente; superficialmente: φ. διατρίβειν ἐν φιλοσοφίᾳ plat. estudar filosofia insuficientemente 3 simplesmente; facilmente; sem esforço.</p></section></article>\n<article id=\"entry-dgp-42374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάψ, φαβός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 168 na letra φ · nº geral 42374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pomba.</p></section></article>\n<article id=\"entry-dgp-42375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάω</h1><div class=\"entry-meta\"><span>DGP · ordem 169 na letra φ · nº geral 42375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª sing. impf. φάε com valor de aor., e fut. perf. πεφήσομαι) brilhar.</p></section></article>\n<article id=\"entry-dgp-42376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φέβομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra φ · nº geral 42376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) fugir tomado de pavor, de medo de alguém, ac.; ser posto em fuga por alguém, ὑπό e dat.</p></section></article>\n<article id=\"entry-dgp-42377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φεβρουάριος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 171 na letra φ · nº geral 42377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Fevereiro, mês ♦ 2 adj. de fevereiro. [lat.]</p></section></article>\n<article id=\"entry-dgp-42378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φέγγος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 172 na letra φ · nº geral 42378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 luminosidade, clarão; luz; esplendor 2 luz (de um corpo celeste): τὸ φ. τοῦ γάλακτος artt. o brilho da Via-Láctea 3 sol: αἱ αὐγαὶ τοῦ φέγγους sept. os raios do sol 4 luz do dia; dia: φ. ἰδεῖν pínd. ver a luz, vir à luz do dia, nascer, λιπεῖν φ. eur. abandonar a luz do dia, morrer 5 ano: δεκάτῳ φέγγει τῷδε ἔτους ésql. eis o décimo ano 6 luz (do fogo, de tochas) 7 brilho dos olhos: τυφλὸν φ. eur. brilho obscurecido dos olhos, cegueira 8 brilho; brancura (do leite) 9 irradiação (de alegria, de felicidade, de riqueza) ♦ τὰ φέγγη 10 fogos da guarda.</p></section></article>\n<article id=\"entry-dgp-42379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φειδίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 173 na letra φ · nº geral 42379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Fídias, escultor ateniense.</p></section></article>\n<article id=\"entry-dgp-42380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδίτιον</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra φ · nº geral 42380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φιδίτιον, ου (τό) refeição em comum (dos lacedemônios com mais de vinte anos).</p></section></article>\n<article id=\"entry-dgp-42381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φείδομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra φ · nº geral 42381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φείσομαι, aor. ἐφεισάμην, perf. πέφεισμαι) 1 tratar com clemência; não maltratar; não destruir; poupar alguém ou algo, gen.: φ. ἀνδρός hom. poupar um homem, φ. Ιλίου hom. poupar Tróia, φ. στρατοῦ sóf. poupar o exército, φ. οὔτε ἰδίον οὔτε δημοσίου οἰκοδομήματος tuc. não poupar nenhum edifício privado ou público, οὐ φ. βίου sóf. ou ψυχῆς dem. não poupar a vida, arriscá-la ousadamente ou sacrificá-la 2 bíbl. ter piedade de, ἀπό ou περί e gen., ἐπί e ac. ou dat. 3 poupar; tratar ou usar com parcimônia, gen. ou ac.: φ. ἵππων hom. poupar cavalos 4 ser cuidadoso com, gen. ou ὑπέρ e gen.: φ. τῆς τοῦ λόγου συμμετρίας plut. preocupar-se com a simetria do discurso 5 viver parcamente; ser parcimonioso 6 abster-se de; evitar, gen.: φ. κινδύνου xen. abster-se do perigo, φ. θαλάσσας evitar o mar, φ. τοῦ λέγειν xen. abster-se de falar ♦ τὸ φειδόμενον 7 clemência 8 economia; moderação.</p></section></article>\n<article id=\"entry-dgp-42382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδομένως</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra φ · nº geral 42382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com economia; moderadamente.</p></section></article>\n<article id=\"entry-dgp-42383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδώ, όος-οῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra φ · nº geral 42383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ἡ) 1 reserva; resguardo; respeito em rel. a alguém ou a algo: φειδώ τις ἐγίγνετο μὴ προαλανωθῆναι tuc. havia um certo resguardo para não sucumbir antecipadamente, φειδώ τινος ἔχειν d.h. ou ποιεῖσθαι s.e. ter consideração por alguém ou algo 2 economia; parcimônia, gen. 3 reserva; discrição; cautela 4 bíbl. indulgência; clemência. 〈φείδομαι〉</p></section></article>\n<article id=\"entry-dgp-42384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδωλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra φ · nº geral 42384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φειδώ.</p></section></article>\n<article id=\"entry-dgp-42385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδωλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra φ · nº geral 42385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">parcimônia; economia. 〈φείδομαι〉</p></section></article>\n<article id=\"entry-dgp-42386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειδωλός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra φ · nº geral 42386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ός, όν 1 parcimonioso; econômico 2 avaro ♦ τὸ φειδωλόν 3 parcimônia 〈φείδομαι〉</p></section></article>\n<article id=\"entry-dgp-42387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φείδων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra φ · nº geral 42387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 frasco de gargalo estreito (para oléo) 2 homem parcimonioso; avaro. 〈φείδομαι〉</p></section></article>\n<article id=\"entry-dgp-42388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φείσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra φ · nº geral 42388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de φείδομαι.</p></section></article>\n<article id=\"entry-dgp-42389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φειστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra φ · nº geral 42389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φείδομαι.</p></section></article>\n<article id=\"entry-dgp-42390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φελλεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra φ · nº geral 42390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ὁ) 1 terreno pedregoso ♦ Φελλεύς (ὁ) 2 Pedregosa, n. de uma região rochosa da Ática. 〈φελλός〉</p></section></article>\n<article id=\"entry-dgp-42391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φέλλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra φ · nº geral 42391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de cortiça. 〈φελλός〉</p></section></article>\n<article id=\"entry-dgp-42392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φελλόποδες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra φ · nº geral 42392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homens como pés de cortiça, povo fictício. 〈φελλός, πούς〉</p></section></article>\n<article id=\"entry-dgp-42393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φελλός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra φ · nº geral 42393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cortiça.</p></section></article>\n<article id=\"entry-dgp-42394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φελλώ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra φ · nº geral 42394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cortiça, ilha fictícia.</p></section></article>\n<article id=\"entry-dgp-42395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φενάκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra φ · nº geral 42395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cabeleira postiça; peruca. 〈φέναξ〉</p></section></article>\n<article id=\"entry-dgp-42396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φενακίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra φ · nº geral 42396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enganar alguém, ac., em algo, ac. ♦ pas. 2 ser enganado em algo, ac., por alguém, ὑπό e gen. 〈φέναξ〉</p></section></article>\n<article id=\"entry-dgp-42397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φενακισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra φ · nº geral 42397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">engano; fraude. 〈φενακίζω〉</p></section></article>\n<article id=\"entry-dgp-42398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φέναξ, ακος</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra φ · nº geral 42398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) traiçoeiro; enganador, impostor.</p></section></article>\n<article id=\"entry-dgp-42399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φεραί, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra φ · nº geral 42399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Feres, cidade da Tessália.</p></section></article>\n<article id=\"entry-dgp-42400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φεραῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra φ · nº geral 42400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Feres. 〈Φεραί〉</p></section></article>\n";
